Hi @kumar007007 

Your example didn't actually work, but it gave me enough to demonstrate the problem: existing templates never get reparsed, even when they are overwritten:

```
 # create test doc
POST testindex/test
{
  "searchtext": "dev1"
}

 # Create bad template
PUT _search/template/git01
{
  "query": {
    "match": {
      "searchtext": {
        "query": "{{P_Keyword1}}",
        "type": "ooophrase_prefix"
      }
    }
  }
}

 # Throws exception
GET testindex/_search/template
{
  "template": {
    "id": "git01"
  },
  "params": {
    "P_Keyword1": "dev"
  }
}

 # Overwrite with correct template
PUT _search/template/git01
{
  "query": {
    "match": {
      "searchtext": {
        "query": "{{P_Keyword1}}",
        "type": "phrase_prefix"
      }
    }
  }
}

 # Search fails with old error
GET testindex/_search/template
{
  "template": {
    "id": "git01"
  },
  "params": {
    "P_Keyword1": "dev"
  }
}

 # Create template with new ID
PUT _search/template/git02
{
  "query": {
    "match": {
      "searchtext": {
        "query": "{{P_Keyword1}}",
        "type": "phrase_prefix"
      }
    }
  }
}

 # Now it works correctly
GET testindex/_search/template
{
  "template": {
    "id": "git02"
  },
  "params": {
    "P_Keyword1": "dev"
  }
}
```

